'use strict';

// Convention: a value of the wrong type raises TypeError; a value of the right
// type that is out of range, non-finite, fractional or blank raises RangeError.

/**
 * Renders a value for an error message. Objects are not coerced with String()
 * because null-prototype objects throw and others print "[object Object]".
 * @param {unknown} value
 * @returns {string}
 */
function describeValue(value) {
  switch (typeof value) {
    case 'string':
      return JSON.stringify(value);
    case 'bigint':
      return `${value}n`;
    case 'function':
      return 'a function';
    case 'object':
      if (value === null) return 'null';
      return Array.isArray(value) ? 'an array' : 'an object';
    default:
      return String(value);
  }
}

/**
 * @param {unknown} value
 * @param {string} label Name of the argument, used in the error message.
 * @throws {TypeError} If `value` is not a string.
 * @throws {RangeError} If `value` is empty or whitespace-only.
 */
function assertNonEmptyString(value, label) {
  if (typeof value !== 'string') {
    throw new TypeError(`${label} must be a string, received ${describeValue(value)}`);
  }
  if (value.trim() === '') {
    throw new RangeError(`${label} must not be empty or whitespace-only, received ${describeValue(value)}`);
  }
}

/**
 * @param {unknown} value
 * @param {string} label Name of the argument, used in the error message.
 * @param {object} [bounds]
 * @param {number} [bounds.min=-Infinity] Inclusive lower bound.
 * @param {number} [bounds.max=Infinity] Inclusive upper bound.
 * @param {boolean} [bounds.integer=false] Require a safe integer.
 * @throws {TypeError} If `value` is not of type number.
 * @throws {RangeError} If `value` is NaN, infinite, out of bounds, or fractional when `integer` is set.
 */
function assertNumberInRange(value, label, { min = -Infinity, max = Infinity, integer = false } = {}) {
  if (typeof value !== 'number') {
    throw new TypeError(`${label} must be a number, received ${describeValue(value)}`);
  }
  if (!Number.isFinite(value)) {
    throw new RangeError(`${label} must be a finite number, received ${value}`);
  }
  if (integer && !Number.isSafeInteger(value)) {
    throw new RangeError(`${label} must be a whole number no greater than Number.MAX_SAFE_INTEGER, received ${value}`);
  }
  if (value < min) {
    throw new RangeError(`${label} must be at least ${min}, received ${value}`);
  }
  if (value > max) {
    throw new RangeError(`${label} must be at most ${max}, received ${value}`);
  }
}

module.exports = { assertNonEmptyString, assertNumberInRange };

